GAPS={13,21}
BUDGET={'max_model_attempts':2,'max_tokens':192,'max_elapsed_ms':90000}
cases=[]
for i,(target,axis,pos,neg,pr,nr) in enumerate(DATA,1):
 for polarity,contexts,rationale in [('positive',pos,pr),('negative',neg,nr)]:
  cid=f'li15-{len(cases)+1:03d}';tid=f'li15-target-{i:02d}'
  signals=[{'kind':kind,'text':text} for kind,text in contexts]
  # Alternate supported fact position without inventing an affirmative grammar.
  signals.insert(0 if i%2 else len(signals),{'kind':'excerpt','text':f'{target} was launched.'})
  inp={'id':cid,'policy':{'policy_id':f'li15-policy-{i:02d}','target_id':tid,'target_question':f'Was {target} launched?','entity':{'canonical_id':tid,'canonical_name':target,'aliases':[]},'relation':'change_or_launch','identity_requirement':'require_harness_anchor','assessment_budget':BUDGET},'candidate':{'evidence_id':cid+'-evidence','source_id':cid+'-synthetic-source','signals':signals},'proposal':{'target_binding':'exact','relation_binding':'exact'},'raw':{'identity_scope':'exact_target','relation_scope':'requested_relation','scope_risk':'context_gap' if i in GAPS and polarity=='negative' else 'none'}}
  cases.append({'id':cid,'pair_id':f'li15-pair-{i:02d}','polarity':polarity,'axis':axis,'expected':{'v17_requested_relation':polarity=='positive','v30_relevant':polarity=='positive'},'rationale':rationale,'input':inp})
def write(n,x):
 with (ROOT/n).open('x') as f:json.dump(x,f,indent=2,ensure_ascii=False);f.write('\n');f.flush();os.fsync(f.fileno())
